B.bt={id:0,name:1,shortDescription:2,longDescription:3,imagePath:4,top:5,left:6,type:7}
B.H2=new A.ba(B.bt,["dome_rock","Dome of the Rock","Iconic gold-domed shrine in the center of the compound.","The Dome of the Rock is an Islamic shrine located at the center of the Al-Aqsa Mosque compound. It was completed in 691 CE and is believed to enshrine the rock from which Prophet Muhammad ascended to heaven during the Isra and Mi\u2019raj.","assets/images/dome_rock.jpg",340,210,"Mosque"],t.W)
B.GW=new A.ba(B.bt,["qibli_mosque","Qibli Mosque","Main prayer hall with a silver dome.","The Qibli Mosque is the southern building within Al-Aqsa, serving as the main congregational prayer hall. It faces the Qibla and is known for its large prayer space and historical architecture.","assets/images/qibli_mosque.jpg",560,210,"Mosque"],t.W)
B.H0=new A.ba(B.bt,["al_marwani","Al-Marwani Mosque","Underground mosque within Solomon's Stables.","Located in the southeastern corner of Al-Aqsa, Al-Marwani is an underground prayer hall built into a series of ancient vaults known as Solomon's Stables.","assets/images/al_marwani.jpg",540,440,"Mosque"],t.W)
B.H4=new A.ba(B.bt,["dome_chain","Dome of the Chain","Small dome next to Dome of the Rock.","The Dome of the Chain is a small open structure adjacent to the Dome of the Rock. Historically, it was a site of justice and preaching.","assets/images/dome_chain.jpg",340,265,"Dome"],t.W)
B.H3=new A.ba(B.bt,["dome_ascension","Dome of the Ascension","Commemorates the Prophet\u2019s ascension.","This small dome marks the traditional location from which the Prophet Muhammad ascended during the Isra and Mi\u2019raj. It is a symbol of this spiritual event.","assets/images/dome_ascension.jpg",300,150,"Dome"],t.W)
B.GZ=new A.ba(B.bt,["dome_khalili","Dome of al-Khalili","Small domed structure named after a sheikh.","This dome is named after Sheikh Khalili and is one of the small structures used for prayer and retreat within the compound.","assets/images/dome_khalili.jpg",175,145,"Dome"],t.W)
B.GY=new A.ba(B.bt,["dome_prophet","Dome of the Prophet","Commemorates the Prophet\u2019s prayer spot.","This dome is believed to mark the spot where the Prophet Muhammad led the previous prophets in prayer before ascending to the heavens.","assets/images/dome_prophet.jpg",310,170,"Dome"],t.W)
B.GX=new A.ba(B.bt,["dome_spirits","Dome of the Spirits","One of the eastern domes.","This dome is one of the smaller domes located toward the eastern side of the Al-Aqsa compound, often used as a peaceful prayer space.","assets/images/dome_spirits.jpg",130,210,"Dome"],t.W)
B.H_=new A.ba(B.bt,["gate_tribes","Gate of the Tribes (Bab al-Asbat)","Northern gate near the Dome of the Rock.","The Gate of the Tribes (Bab al-Asbat) is located at the northeastern corner of the Al-Aqsa Mosque compound and is historically used for access to residential areas around the site.","assets/images/gate_tribes.jpg",100,480,"Gate"],t.W)
B.H1=new A.ba(B.bt,["islamic_museum","The Islamic Museum","Museum holding Islamic artifacts.","Located near the southwestern edge of the compound, this museum holds manuscripts, ceramics, and other valuable Islamic artifacts.","assets/images/islamic_museum.jpg",620,120,"Building"],t.W)
B.Fd=A.b(s([B.H2,B.GW,B.H0,B.H4,B.H3,B.GZ,B.GY,B.GX,B.H_,B.H1]),t.H7)
